'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>name==='git-fork'?`<svg class="pistachio-icon" viewBox="0 0 32 32" fill="none" aria-label="Antep fıstığı ağacı"><path d="M16 29V14m0 8-7-6m7 2 7-6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M5 15C1 8 10 2 15 8 17 0 28 3 26 11 33 15 25 22 19 17 14 23 7 21 5 15Z" fill="#81916a" fill-opacity=".3" stroke="currentColor" stroke-width="1.4"/><ellipse cx="10" cy="11" rx="2" ry="3" fill="#b89166"/><ellipse cx="23" cy="14" rx="2" ry="3" fill="#b89166"/></svg>`:`<i data-lucide="${name}" aria-hidden="true"></i>`;
const initials=n=>String(n||'?').split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('');
const avatar=(p,cls='')=>`<span class="avatar ${cls}">${esc(initials(typeof p==='string'?p:p.name))}</span>`;
const dateText=(d,opts={day:'numeric',month:'long',year:'numeric'})=>d?new Date(d+'T12:00:00').toLocaleDateString('tr-TR',opts):'Tarih bilinmiyor';
const roleName={owner:'Aile yöneticisi',moderator:'Moderatör',member:'Aile üyesi'};
const types={birthday:'Doğum günü',marriage:'Evlilik yıldönümü',memorial:'Anma günü',funeral:'Cenaze',gathering:'Aile buluşması',migration:'Göç',story:'Aile hikâyesi'};
const typeIcon={birthday:'cake',marriage:'heart',memorial:'flower-2',funeral:'flower-2',gathering:'users-round',migration:'map-pin',story:'book-open'};
const navItems=[['home','house','Aile Konağı'],['tree','git-fork','Soy Ağacı'],['people','users-round','Aile üyeleri'],['gallery','images','Avlu'],['calendar','calendar-days','Aile takvimi'],['history','book-open','Geçmişten Günümüze'],['places','map-pin','Bizimkiler Nerede?'],['chat','messages-square','Aile Sohbetleri'],['documents','files','Aile Sandığı'],['archive','library','Yaşayan Arşiv'],['connections','route','Aile Bağlarımız'],['groups','users-round','Aile Grupları']];
let demoMode=!!window.SF_PREVIEW||location.protocol==='file:'||new URLSearchParams(location.search).get('demo')==='1';
let demo=demoMode?window.makeDemo():null,csrf='',hostedAuth=false,state=null,adminData=null,route='home',personId='',filter='all',query='',page=1,photoQuery='',calendarMonth=new Date(),selectedDate=null,zoom=1,treeFocus='',toastTimer,lastFocus;
const dialog=$('#dialog');
async function api(path,method='GET',data){if(demo)return demo.request(path,method,data);const transport=window.FamilyNative?.available?window.FamilyNative.request:fetch;const res=await transport(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(sessionStorage.getItem('sf-factor')?{'X-Family-Factor':sessionStorage.getItem('sf-factor')}:{})},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await res.json();}catch{throw Error('Sunucuyla bağlantı kurulamadı.');}if(res.status===428){await archiveFactorPrompt();return api(path,method,data);}if(!res.ok)throw Error(body.error||'İşlem tamamlanamadı.');return body;}
const isStaff=()=>state&&state.user.role!=='member',isOwner=()=>state?.user.role==='owner';
const button=(label,action,ico,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const empty=(title,desc,action='',label='Yeni kayıt ekle')=>`<div class="empty">${icon('sprout')}<h3>${title}</h3><p>${desc}</p>${action?button(label,action,'plus'):''}</div>`;
const input=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const area=(label,name,value='',extra='')=>`<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;
function select(label,name,options,value='',extra=''){return`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function hydrate(){window.lucide?.createIcons();}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function modal(title,content,wide=false){lastFocus=document.activeElement;dialog.style.width=wide?'min(900px,calc(100% - 32px))':'';dialog.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Pencereyi kapat">${icon('x')}</button></div><div class="dialog-body">${content}</div>`;if(!dialog.open)dialog.showModal();hydrate();}
function closeModal(){dialog.close();lastFocus?.focus?.();}
function form(content,label='Kaydet'){return`<form id="modal-form"><div class="form-grid">${content}</div><div class="form-error" role="alert"></div><div class="form-actions">${button('Vazgeç','close',null,'','type="button"')}<button class="btn primary" type="submit">${icon('check')}${label}</button></div></form>`;}
function submitWith(callback){$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f)),submit=$('[type=submit]',f),error=$('.form-error',f);submit.disabled=true;error.textContent='';try{await callback(b,f);}catch(err){error.textContent=err.message;}finally{submit.disabled=false;}});}
async function refresh(){state=await api('/api/bootstrap');await window.archiveApp?.load();if(isStaff()&&['admin','settings'].includes(route))adminData=await api('/api/admin');render();}
function go(next,id=''){route=next;personId=id;filter='all';query='';page=1;selectedDate=null;location.hash=next==='profile'?'person/'+id:next;render();window.scrollTo({top:0,behavior:'instant'});}
function readRoute(){const h=location.hash.slice(1);if(h.startsWith('person/')){route='profile';personId=h.slice(7);}else if(navItems.some(n=>n[0]===h)||['admin','settings'].includes(h))route=h;else route='home';}
function approvedEvents(){return state.events.filter(e=>e.status==='approved');}
function annual(d){const [year,m,day]=d.split('-').map(Number),today=new Date(),midnight=new Date(today.getFullYear(),today.getMonth(),today.getDate());let y=today.getFullYear(),next=new Date(y,m-1,day);if(next.getMonth()!==m-1)next=new Date(y,m,0);if(next<midnight){y++;next=new Date(y,m-1,day);if(next.getMonth()!==m-1)next=new Date(y,m,0);}return{date:`${y}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`,years:y-year};}
function upcoming(){const events=approvedEvents().map(e=>({...e,...(['birthday','marriage','memorial'].includes(e.type)?annual(e.date):{})}));for(const p of state.people){if(p.birthDate&&!p.deathDate)events.push({id:'birth-'+p.id,title:p.name,type:'birthday',personId:p.id,...annual(p.birthDate),place:p.place});if(p.deathDate)events.push({id:'death-'+p.id,title:p.name,type:'memorial',personId:p.id,...annual(p.deathDate),place:p.place});}for(const r of state.relations.filter(r=>r.type==='spouse'&&r.date)){const a=state.people.find(p=>p.id===r.personA),b=state.people.find(p=>p.id===r.personB);if(a&&b&&!a.deathDate&&!b.deathDate)events.push({id:r.id,title:`${a.name.split(' ')[0]} & ${b.name.split(' ')[0]}`,type:'marriage',...annual(r.date),place:a.place});}return events.sort((a,b)=>a.date.localeCompare(b.date));}
function generationMap(){const byId=new Map(state.people.map(p=>[p.id,p])),parents=new Map(),memo=new Map();state.relations.filter(r=>r.type!=='spouse').forEach(r=>{if(byId.has(r.personA)&&byId.has(r.personB)){if(!parents.has(r.personB))parents.set(r.personB,[]);parents.get(r.personB).push(r.personA);}});function depth(id,seen=new Set()){if(memo.has(id))return memo.get(id);if(seen.has(id))return 0;seen.add(id);const d=Math.max(0,...(parents.get(id)||[]).map(p=>depth(p,new Set(seen))+1));memo.set(id,d);return d;}state.people.forEach(p=>depth(p.id));return memo;}
function statCards(){const levels=generationMap(),countries=new Set(state.people.map(p=>p.country).filter(Boolean));return`<div class="stats">${[[state.people.length,'Aile üyesi','users-round'],[levels.size?Math.max(...levels.values())+1:0,'Bir arada nesil','git-fork'],[state.photoCount??state.photos.filter(p=>p.status==='approved').length,'Arşivde fotoğraf','images'],[countries.size,'Ülkede ailemiz','globe-2']].map(([v,l,i])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><strong>${v.toLocaleString('tr-TR')}</strong><small>${l}</small></div></div>`).join('')}</div>`;}
function eventRows(events){return events.length?events.map(e=>`<button class="event-row" style="width:100%;text-align:left" data-action="event-detail" data-id="${esc(e.id)}"><span class="event-date"><strong>${new Date(e.date+'T12:00:00').getDate()}</strong><small>${dateText(e.date,{month:'short'})}</small></span><span><h3>${esc(e.title)}</h3><p>${types[e.type]}${e.years?' · '+e.years+'. yıl':''}</p></span>${icon(typeIcon[e.type]||'calendar-days')}</button>`).join(''):empty('Takvimimiz sakin','Yeni tarihler burada yer alacak.');}
function home(){const today=new Date().toLocaleDateString('en-CA'),events=upcoming().filter(e=>e.date>=today).slice(0,3),photos=state.photos.filter(p=>p.status==='approved'),first=state.user.name.split(' ')[0];return`<div class="greeting"><div><span class="eyebrow">AYNI KÖKTEN, BİNLERCE HİKÂYE</span><h1>Evine hoş geldin, ${esc(first)}.</h1><p>Uzakta olsak da birbirimize ait olduğumuz bir yer var.</p></div>${button('Bir anı paylaş','upload','plus')}</div><section class="hero" aria-label="Ailemizin hikâyesi"><img src="assets/heritage.webp" alt="Halfeti’den ilhamla üretilmiş temsili taş evler ve nehir manzarası"><span class="hero-label">Bizim ailemiz. Bizim hikâyemiz.</span><div class="hero-copy"><span class="eyebrow">SARIÇİÇEK AİLE KONAĞI</span><h1>Köklerimiz bir.<br><em>Hikâyemiz sonsuz.</em></h1><p>Geçmişimizi birlikte hatırlıyor, bugünümüzü paylaşıyor, yarınlara iz bırakıyoruz.</p>${button('Hikâyemizi keşfet','nav','arrow-up-right','','data-page="history"')}</div><span class="hero-location">${icon('map-pin')}Halfeti’den ilhamla · Temsili görsel</span></section>${statCards()}<div class="home-grid"><section class="card"><div class="section-head"><h2>Anılarımızın izinde</h2><button class="text-btn" data-action="nav" data-page="gallery">Arşive göz at ${icon('arrow-right')}</button></div><div class="archive-feature"><img src="${esc(photos[0]?.url||'assets/archive.webp')}" alt="${esc(photos[0]?.title||'Temsili aile arşivi')}" loading="lazy"><div><span class="eyebrow">DÜNDEN YARINA</span><h3>Bir fotoğraf.<br>Binlerce hatıra.</h3><p>Birlikte gülümseyen yüzler, unutulmasın istediğimiz anlar. Aile albümümüzü birlikte büyütelim.</p><button class="text-btn" data-action="upload">Sen de bir anı ekle ${icon('arrow-up-right')}</button></div></div></section><section class="card"><div class="section-head"><h2>Yaklaşan günler</h2><button class="text-btn" data-action="nav" data-page="calendar">Takvimi aç ${icon('arrow-right')}</button></div>${eventRows(events)}</section></div><div class="heritage-band"><div class="quote-card"><p>“İnsan, köklerini bildiği<br>yerde yeniden çiçek açar.”</p><div class="eyebrow">GEÇMİŞTEN GELEN, GELECEĞE KALAN</div>${icon('sprout')}</div><section class="card"><div class="section-head"><h2>Aileden izler</h2><button class="text-btn" data-action="nav" data-page="people">Ailemizi gör ${icon('arrow-right')}</button></div>${[...state.people].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,2).map(p=>`<button class="activity-row" data-action="profile" data-id="${esc(p.id)}" style="width:100%;text-align:left">${avatar(p)}<span><p><strong>${esc(p.name)}</strong> · Aile ağacımızda</p><small>${esc(p.place||'Birlikte yazılan bir hikâye')}</small></span></button>`).join('')||'<p>İlk aile üyesini ekleyerek başlayın.</p>'}</section></div>`;}
function heading(kicker,title,desc,actions=''){return`<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div><div class="row">${actions}</div></div>`;}
function people(){const all=state.people.filter(p=>(filter==='all'||(filter==='living'&&!p.deathDate)||(filter==='deceased'&&p.deathDate))&&`${p.name} ${p.place} ${p.country}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))),list=all.slice((page-1)*24,page*24);return heading('BİZİ BİZ YAPAN','Her isim, bir hikâye.','Ailemizin farklı kuşaklarını tanı; aramızdaki bağları keşfet.',isStaff()?button('Aile üyesi ekle','add-person','plus','primary'):'')+`<div class="toolbar"><div class="tabs">${[['all','Tüm aile'],['living','Yaşayanlar'],['deceased','Sevgiyle andıklarımız']].map(([v,l])=>`<button class="tab ${filter===v?'active':''}" data-action="filter" data-filter="${v}">${l}</button>`).join('')}</div><label class="search">${icon('search')}<input id="people-search" placeholder="İsim, şehir veya ülke ara" value="${esc(query)}" aria-label="Aile üyelerinde ara"></label></div><p class="muted member-list-filter" style="font-size:10px">${all.length} aile üyesi</p><div class="grid-people">${list.map(p=>`<button class="person-card" data-action="profile" data-id="${esc(p.id)}">${p.deathDate?`<span class="memorial-mark">${icon('flower-2')}</span>`:''}${avatar(p)}<h3>${esc(p.name)}</h3><p>${esc(p.place||'Konum eklenmedi')}${p.country?' · '+esc(p.country):''}</p><span class="life">${p.birthDate?p.birthDate.slice(0,4):'?'}${p.deathDate?' — '+p.deathDate.slice(0,4):''}</span><span class="text-btn">Hikâyesini gör ${icon('arrow-up-right')}</span></button>`).join('')}</div>${!list.length?empty('Henüz bir kayıt yok','Aramanı değiştir veya ailemize birini ekle.',isStaff()?'add-person':''):''}${all.length>24?`<div class="pagination">${button('Önceki','prev-page','chevron-left','small',page===1?'disabled':'')}<span>${page} / ${Math.ceil(all.length/24)}</span>${button('Sonraki','next-page','chevron-right','small',page*24>=all.length?'disabled':'')}</div>`:''}`;}
function gallery(){const list=state.photos.filter(p=>(filter==='all'?p.status==='approved':filter==='mine'?p.createdBy===state.user.id:p.status==='pending')&&`${p.title} ${p.place}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));return heading('BİRLİKTE BİRİKTİRDİK','Hatıraların evi.','Bir fotoğrafın ardında saklı kalan hikâyeyi gelecek kuşaklara bırakalım.',button('Fotoğraf ekle','upload','plus','primary'))+`<div class="gallery-banner">${icon('image-plus')}<div><h3>En güzel anılar, paylaşılanlar.</h3><p>Fotoğrafını yükle, içindeki kişileri etiketle, hikâyesini anlat.</p></div>${button('Arşive katkıda bulun','upload','arrow-up-right')}</div><div class="toolbar"><div class="tabs">${[['all','Aile arşivi'],['mine','Benim eklediklerim'],...(isStaff()?[['pending','Onay bekleyenler']]:[])].map(([v,l])=>`<button class="tab ${filter===v?'active':''}" data-action="filter" data-filter="${v}">${l}</button>`).join('')}</div><label class="search">${icon('search')}<input id="gallery-search" placeholder="Yüklenen anılarda ara…" value="${esc(query)}" aria-label="Avlunde ara"></label></div><div class="gallery-grid">${list.map(p=>`<button class="photo-card" data-action="photo" data-id="${esc(p.id)}"><div class="photo-top"><img src="${esc(p.url)}" alt="${esc(p.title)}" loading="lazy">${p.illustration?'<span class="photo-badge">Temsili görsel</span>':''}</div><div class="photo-meta"><h3>${esc(p.title)}</h3><p>${esc(p.place||'Aile arşivi')} · ${p.date?dateText(p.date,{year:'numeric'}):'Tarih bilinmiyor'}</p>${p.status!=='approved'?`<span class="pill ${p.status}">${p.status==='pending'?'Onay bekliyor':'Yayımlanmadı'}</span>`:''}</div></button>`).join('')}</div>${state.photos.length>=200&&!state.photosComplete?'<div class="pagination">'+button('Daha fazla fotoğraf yükle','load-photos','chevron-down')+'</div>':''}${!list.length?empty('Bu albüm birlikte dolacak.','İlk fotoğrafını ve ardındaki hikâyeyi paylaş.','upload','İlk fotoğrafı ekle'):''}`;}
function tree(){const levels=generationMap(),ranks=new Map(levels);for(let i=0;i<2;i++)for(const r of state.relations.filter(r=>r.type==='spouse')){if(ranks.has(r.personA)&&ranks.has(r.personB)){const l=Math.max(ranks.get(r.personA),ranks.get(r.personB));ranks.set(r.personA,l);ranks.set(r.personB,l);}}
 let list=state.people;if(treeFocus){const ids=new Set([treeFocus]);for(let i=0;i<2;i++){const snapshot=new Set(ids);for(const r of state.relations)if(snapshot.has(r.personA)||snapshot.has(r.personB)){ids.add(r.personA);ids.add(r.personB);}}list=list.filter(p=>ids.has(p.id));}if(list.length>120)list=list.slice(0,120);
 const rows=new Map();for(const p of list){const l=ranks.get(p.id)||0;if(!rows.has(l))rows.set(l,[]);rows.get(l).push(p);}const width=Math.max(800,...[...rows.values()].map(r=>r.length*195+80)),height=Math.max(540,(rows.size+1)*170);const coords=new Map();[...rows.entries()].sort((a,b)=>a[0]-b[0]).forEach(([level,row],ri)=>row.forEach((p,i)=>coords.set(p.id,{x:(width-row.length*195)/2+i*195,y:50+ri*165})));const paths=state.relations.filter(r=>coords.has(r.personA)&&coords.has(r.personB)).map(r=>{const a=coords.get(r.personA),b=coords.get(r.personB);if(r.type==='spouse')return`<path d="M${a.x+84} ${a.y+50} L${b.x+84} ${b.y+50}" stroke="#b5a575" stroke-dasharray="4 4"/>`;return`<path d="M${a.x+84} ${a.y+99} V${(a.y+b.y+99)/2} H${b.x+84} V${b.y}" stroke="#9bab89" ${r.type==='adoptive'?'stroke-dasharray="5 4"':''}/>`;}).join('');
 return heading('KÖKLERİMİZ VE DALLARIMIZ','Birbirimize bağlıyız.','Her dal bir yolculuk, her bağ bizi bir arada tutan bir hikâye.',isStaff()?button('PDF / Yazdır','print-tree','printer')+button('İlişki ekle','add-relation','link-2')+button('Kişi ekle','add-person','plus','primary'):'')+`<div class="toolbar"><label class="search">${icon('search')}<input id="tree-search" placeholder="Ağaçta birini bul…" aria-label="Ağaçta kişi ara"></label><div class="row">${treeFocus?button('Tüm ağaca dön','tree-reset','git-fork','small'):''}<span class="muted" style="font-size:10px">${list.length} kişi görüntüleniyor</span></div></div><div class="tree-board"><div class="tree-viewport"><div class="tree-canvas" style="width:${width}px;height:${height}px;transform:scale(${zoom})"><svg width="${width}" height="${height}" fill="none" stroke-width="1.4">${paths}</svg>${list.map(p=>{const c=coords.get(p.id);return`<button class="tree-node ${p.id===treeFocus?'selected':''}" style="left:${c.x}px;top:${c.y}px" data-action="profile" data-id="${esc(p.id)}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${p.birthDate?p.birthDate.slice(0,4):'?'}${p.deathDate?' – '+p.deathDate.slice(0,4):''}</small></span></button>`;}).join('')}</div></div><div class="tree-tools"><button data-action="zoom-out" aria-label="Uzaklaştır">${icon('minus')}</button><span id="zoom-label">${Math.round(zoom*100)}%</span><button data-action="zoom-in" aria-label="Yakınlaştır">${icon('plus')}</button><button data-action="zoom-fit" aria-label="Ekrana sığdır">${icon('maximize')}</button></div><div class="tree-legend"><span>Ebeveyn / çocuk</span><span>Eş bağı (kesikli)</span></div></div><p class="tree-note">${state.people.length>120?'Büyük ağaçlarda ilk 120 kişi gösterilir. Aramayla bir aile dalına odaklanın.':'Kartlara dokunarak kişi profilini açabilirsiniz. Ağacı sürükleyerek veya kaydırarak gezin.'}</p>${!state.people.length?empty('Köklerimizi birlikte çizelim.','İlk aile üyesini ekleyerek başlayın.',isStaff()?'add-person':''):''}`;}
function calendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),events=upcoming(),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;const monthEvents=events.filter(e=>e.date.startsWith(`${y}-${String(m+1).padStart(2,'0')}`)),list=selectedDate?monthEvents.filter(e=>e.date===selectedDate):monthEvents;return heading('UNUTULMASIN DİYE','Birlikte hatırlayalım.','Doğum günleri, yıldönümleri, buluşmalar ve sevgiyle andıklarımız.',button('Takvime ekle','add-event','plus','primary'))+`<div class="calendar-layout"><section class="card"><div class="section-head"><h2>${calendarMonth.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</h2><div class="row"><button class="icon-btn" data-action="month-prev" aria-label="Önceki ay">${icon('chevron-left')}</button><button class="icon-btn" data-action="month-next" aria-label="Sonraki ay">${icon('chevron-right')}</button></div></div><div class="calendar-grid">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="day outside"></div>').join('')}${Array.from({length:days},(_,i)=>{const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,ev=monthEvents.filter(e=>e.date===d);return`<button class="day ${today===d?'today':''} ${selectedDate===d?'selected':''}" data-action="select-day" data-date="${d}" aria-label="${dateText(d)}${ev.length?', '+ev.length+' etkinlik':''}">${i+1}<br>${ev.map(()=>'<span class="day-dot"></span>').slice(0,3).join('')}${ev[0]?`<span class="day-label">${esc(ev[0].title)}</span>`:''}</button>`;}).join('')}</div><div class="notice">Doğum günleri ve evlilik yıldönümleri kayıtlı tarihlerden otomatik hesaplanır.</div></section><section class="card"><div class="section-head"><h2>${selectedDate?dateText(selectedDate,{day:'numeric',month:'long'}):'Bu ay ailemizde'}</h2>${selectedDate?'<button class="text-btn" data-action="clear-day">Tüm ay</button>':''}</div>${eventRows(list)}${list.length?button('Takvime indir','export-calendar','download','small','style="margin-top:20px"'):''}</section></div>`;}
function historyPage(){return heading('DÜNDEN YARINA','Geçmişten Günümüze','Anlatılmayan hikâyeler kaybolur. Ailemizin hafızasını birlikte yaşatalım.',button('Bir hikâye ekle','add-story','plus','primary')+button('Aile Sandığı','nav','files','','data-page="documents"'))+`<section class="card archive-feature" style="grid-template-columns:1fr 1fr;padding:27px"><div><span class="eyebrow">${esc(state.settings.familyTitle)} AİLESİ</span><h2 style="margin:12px 0 17px">Geçmişten gelen,<br>geleceğe kalan.</h2><p class="bio">${esc(state.settings.familyStory)}</p></div><img src="assets/archive.webp" alt="Temsili arşiv fotoğrafları ve mektuplar" style="height:285px"></section><div class="timeline">${approvedEvents().filter(e=>['story','migration','memorial','marriage','funeral'].includes(e.type)).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<article class="timeline-item"><div class="timeline-year">${e.date.slice(0,4)}</div><div class="card"><span class="eyebrow">${types[e.type]}</span><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="row between" style="margin-top:14px"><small class="muted">${dateText(e.date)}${e.place?' · '+esc(e.place):''}</small><button class="text-btn" data-action="event-detail" data-id="${esc(e.id)}">${icon('arrow-up-right')}</button></div></div></article>`).join('')}</div>${!approvedEvents().some(e=>['story','migration','memorial','marriage','funeral'].includes(e.type))?empty('Hikâyemizin ilk sayfası','Bir anıyı, bir göçü veya aile büyüğünün anlatısını kaydet.','add-story','Hikâye ekle'):''}`;}
function places(){return communityPlaces();}
function legacyPlaces(){const groups=new Map();for(const p of state.people.filter(p=>!p.deathDate&&p.place)){const key=p.place+' · '+(p.country||'');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);}return heading('MESAFELER DEĞİŞİR, BAĞLAR KALIR','Dünyaya yayılan ailemiz.','Üyelerin kaydettiği şehir ve ülkelere göre ailemizin yaşadığı yerler.')+`<div class="map-list">${[...groups.entries()].sort((a,b)=>b[1].length-a[1].length).map(([place,people])=>`<article class="place-card">${icon('map-pin')}<h3>${esc(place.split(' · ')[0])}</h3><p>${esc(place.split(' · ')[1])} · ${people.length} aile üyesi</p><div style="margin-top:18px">${people.slice(0,5).map(p=>`<button class="family-link" data-action="profile" data-id="${esc(p.id)}">${avatar(p)}<strong>${esc(p.name)}</strong>${icon('arrow-up-right')}</button>`).join('')}</div></article>`).join('')}</div>${!groups.size?empty('Mesafeleri birlikte aşalım.','Kişi profillerine şehir ve ülke eklediğinizde burada görünür.'):''}`;}
function profile(){const p=state.people.find(x=>x.id===personId);if(!p)return empty('Kişi bulunamadı.','Bu kayıt kaldırılmış olabilir.');const relations=state.relations.filter(r=>r.personA===p.id||r.personB===p.id),family=relations.map(r=>({p:state.people.find(x=>x.id===(r.personA===p.id?r.personB:r.personA)),label:r.type==='spouse'?'Eşi':r.personA===p.id?(r.type==='adoptive'?'Evlatlık bağı · çocuğu':'Çocuğu'):(r.type==='adoptive'?'Evlatlık bağı · ebeveyni':'Ebeveyni')})).filter(x=>x.p),photos=state.photos.filter(x=>x.peopleIds?.includes(p.id)&&x.status==='approved');let age='';if(p.birthDate){const start=new Date(p.birthDate),end=p.deathDate?new Date(p.deathDate):new Date();let n=end.getFullYear()-start.getFullYear();if(end.getMonth()<start.getMonth()||end.getMonth()===start.getMonth()&&end.getDate()<start.getDate())n--;age=n+' yaş'+(p.deathDate?'ında aramızdan ayrıldı':'ında');}return`<button class="text-btn" data-action="nav" data-page="people" style="margin-bottom:20px">${icon('arrow-left')} Aile üyeleri</button><div class="profile-hero">${avatar(p,'large')}<div><span class="eyebrow">${p.deathDate?'SEVGİYLE VE ÖZLEMLE':'AİLEMİZİN BİR PARÇASI'}</span><h1 style="margin-top:9px">${esc(p.name)}</h1><p>${esc(p.place)}${p.country?' · '+esc(p.country):''}${age?' · '+age:''}</p></div></div><div class="row" style="margin-top:18px;flex-wrap:wrap">${button('Ağaçta göster','focus-person','git-fork','','data-id="'+esc(p.id)+'"')}${isStaff()?button('Profili düzenle','edit-person','pencil','','data-id="'+esc(p.id)+'"'):''}</div><div class="profile-grid"><section class="card"><div class="section-head"><h2>Hayatından izler</h2></div><p class="bio">${esc(p.biography||'Bu hikâye henüz yazılmadı. Ailemizin bu üyesi hakkında bildiklerinizi paylaşın.')}</p><div style="margin-top:22px">${[['Doğum tarihi',dateText(p.birthDate)],...(p.deathDate?[['Vefat tarihi',dateText(p.deathDate)]]:[]),['Yaşadığı yer',p.place||'Eklenmedi'],['Bilginin kaynağı',p.source||'Henüz belirtilmedi']].map(([k,v])=>`<div class="detail"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div></section><section class="card"><h2>Aile bağları</h2><div style="margin-top:15px">${family.map(f=>`<button class="family-link" data-action="profile" data-id="${esc(f.p.id)}">${avatar(f.p)}<span><strong>${esc(f.p.name)}</strong><small>${f.label}</small></span></button>`).join('')||'<p style="font-size:12px">Henüz ilişki eklenmedi.</p>'}</div>${isStaff()?button('Aile bağı ekle','add-relation','link-2','small','style="margin-top:18px"'):''}</section></div><section class="card" style="margin-top:23px"><div class="section-head"><h2>Fotoğraflardaki hikâyesi</h2><span class="muted">${photos.length} fotoğraf</span></div><div class="gallery-grid">${photos.map(ph=>`<button class="photo-card" data-action="photo" data-id="${esc(ph.id)}"><img src="${esc(ph.url)}" alt="${esc(ph.title)}"><div class="photo-meta"><h3>${esc(ph.title)}</h3></div></button>`).join('')}</div>${!photos.length?'<p style="font-size:12px">Fotoğraflarda bu kişiyi etiketlediğinizde burada görünür.</p>':''}</section>`;}
async function loadAdmin(){adminData=await api('/api/admin');render();}
function admin(){if(!isStaff())return empty('Bu bölüm yetki gerektiriyor.','Yönetim alanını yalnızca yöneticiler ve moderatörler kullanabilir.');if(!adminData){loadAdmin().catch(e=>toast(e.message));return'<p>Yönetim alanı yükleniyor…</p>';}
 const pending=[...state.photos.filter(p=>p.status==='pending').map(p=>({...p,table:'photos'})),...state.events.filter(p=>p.status==='pending').map(p=>({...p,table:'events'}))];return heading('AİLEMİZE ÖZENLE','Birlikte, güvenle.','Katkıları gözden geçir, aile kayıtlarını koru ve üyelikleri yönet.',(isOwner()?button('Üye davet et','invite','user-plus','primary'):'')+button('Mesaj bildirimleri','chat-reports','flag'))+`<div class="rights">${[['owner','shield-check','Üyeleri davet eder, yetkilendirir ve tüm ayarları yönetir.'],['moderator','badge-check','Kişileri ve aile bağlarını düzenler, paylaşımları onaylar.'],['member','heart-handshake','Aile arşivini görür, fotoğraf ve olay paylaşır.']].map(([r,i,d])=>`<div>${icon(i)}<strong>${roleName[r]}</strong><p>${d}</p></div>`).join('')}</div><section class="card"><div class="section-head"><h2>Onay bekleyen katkılar</h2><span class="pill">${pending.length} kayıt</span></div>${pending.map(p=>`<div class="event-row"><div style="flex:1"><h3>${esc(p.title)}</h3><p>${p.table==='photos'?'Fotoğraf':'Aile olayı'} · ${p.date?dateText(p.date):''}</p></div>${button('İncele',p.table==='photos'?'photo':'event-detail','eye','small','data-id="'+esc(p.id)+'"')}${button('Onayla','approve','check','small','data-id="'+esc(p.id)+'" data-table="'+p.table+'"')}${button('Reddet','reject','x','small','data-id="'+esc(p.id)+'" data-table="'+p.table+'"')}</div>`).join('')||'<p style="font-size:12px">Tüm katkılar gözden geçirilmiş. Bekleyen kayıt yok.</p>'}</section>${isOwner()?`<section class="card" style="margin-top:22px"><div class="section-head"><h2>Üyeler ve yetkiler</h2><span class="muted" style="font-size:11px">${adminData.users.length} hesap</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Üye</th><th>Yetki</th><th>Durum</th><th>İşlemler</th></tr></thead><tbody>${adminData.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${u.role==='owner'?'Aile yöneticisi':`<select data-user-role="${esc(u.id)}" aria-label="${esc(u.name)} yetkisi"><option value="member" ${u.role==='member'?'selected':''}>Aile üyesi</option><option value="moderator" ${u.role==='moderator'?'selected':''}>Moderatör</option></select>`}</td><td><span class="pill ${u.active?'':'rejected'}">${u.active?'Aktif':'Donduruldu'}</span></td><td>${u.role!=='owner'?button(u.active?'Dondur':'Etkinleştir','toggle-user',null,'small','data-id="'+esc(u.id)+'"')+(hostedAuth?'':button('Şifre yenile','reset-link',null,'small','data-id="'+esc(u.id)+'"')):''}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:22px"><div class="section-head"><h2>Davetler</h2></div>${adminData.invites.length?adminData.invites.map(i=>`<div class="event-row"><div style="flex:1"><h3>${esc(i.email)}</h3><p>${roleName[i.role]} · ${i.used?'Katıldı':i.expires<Date.now()?'Süresi doldu':'Kabul bekleniyor'}</p></div>${!i.used?button('İptal et','cancel-invite',null,'small','data-id="'+esc(i.id)+'"'):''}</div>`).join(''):'<p style="font-size:12px">Henüz davet oluşturulmadı.</p>'}</section>`:''}<div class="admin-grid" style="margin-top:22px"><section class="card"><div class="section-head"><h2>Değişiklik geçmişi</h2></div>${adminData.audit.slice(0,10).map(a=>`<div class="detail"><strong>${esc(a.action)}</strong><small>${esc(a.name||'Yönetici')} · ${new Date(a.createdAt).toLocaleString('tr-TR')}</small></div>`).join('')||'<p style="font-size:12px">Yeni işlemler burada kaydedilir.</p>'}</section><section class="card"><div class="section-head"><h2>Kaldırılan kayıtlar</h2></div>${Object.entries(adminData.trash).flatMap(([table,items])=>items.map(i=>`<div class="event-row"><h3 style="flex:1">${esc(i.name||i.title)}</h3>${button('Geri yükle','restore','rotate-ccw','small','data-id="'+esc(i.id)+'" data-table="'+table+'"')}</div>`)).join('')||'<p style="font-size:12px">Kaldırılan kayıt bulunmuyor.</p>'}</section></div>`;}
function settingsPage(){if(!isOwner())return empty('Bu bölüm aile yöneticisine açık.','Yetki ve alan adı ayarları yönetici tarafından düzenlenir.');return heading('KONAĞIN DÜZENİ','Ailemize özel.','Aile hikâyesini, alan adı planını ve arşivini buradan yönet.')+`<div class="admin-grid"><section class="card"><h2>Aile kimliği</h2><form id="settings-form" class="stack" style="margin-top:20px">${input('Aile adı','familyTitle',state.settings.familyTitle,'text','required maxlength="100"')}${area('Ailemizin hikâyesi','familyStory',state.settings.familyStory)}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">${icon('check')}Değişiklikleri kaydet</button></form></section><section class="card"><h2>Alan adımız ve e-posta</h2><p style="font-size:12px;margin:15px 0">Kendi alan adınızı kullanarak aile üyeleri için kişisel e-posta adresleri planlayın.</p><form id="domain-form">${input('Alan adı','mailDomain',state.settings.mailDomain,'text','placeholder="ailenizin-alanadi.com"')}<div class="notice">Alan adı ve posta kutusu hizmeti henüz bağlı değil. Buraya yazmak alan adını satın almaz veya e-posta kutusu oluşturmaz. Posta kutuları seçtiğiniz sağlayıcıda açıldıktan sonra bu adresleri üyelik davetlerinde kullanabilirsiniz.</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary">${icon('check')}Alan adını kaydet</button></form>${button('E-posta planını indir','mail-plan','download','','style="margin-top:15px"')}</section><section class="card"><h2>Arşiv yedeği</h2><p style="font-size:12px;margin:15px 0 20px">Kişileri, ilişkileri ve kayıt bilgilerini JSON olarak dışa aktarın. Fotoğraf dosyaları ayrıca sunucu yedeğiyle korunur.</p>${button('Kayıtları dışa aktar','export','download')}</section>${demoMode?`<section class="card"><h2>Önizleme rolleri</h2><p style="font-size:12px;margin:15px 0">Aynı tasarımın farklı yetkilerdeki görünümünü deneyin. Bu alan yalnızca örnek verili önizlemede bulunur.</p><div class="row" style="flex-wrap:wrap">${['owner','moderator','member'].map(r=>button(roleName[r],'demo-role',null,'small','data-role="'+r+'"')).join('')}</div></section>`:''}</div>`;}
function render(){if(!state)return;const current=navItems.find(x=>x[0]===route)?.[2]||({profile:'Aile profili',admin:'Yönetim',settings:'Aile ayarları'}[route]||'Aile Konağı');const pending=state.photos.filter(p=>p.status==='pending').length+state.events.filter(p=>p.status==='pending').length;$('#app').innerHTML=`<div class="shell"><header class="topbar social-topbar"><a class="brand" href="#home"><img src="assets/mark.svg" alt="Sarıçiçek"><span><strong>Sarıçiçek</strong><small>AİLE KONAĞI</small></span></a><nav class="desktop-links" aria-label="Ana menü">${navItems.filter(n=>['home','gallery','tree','history','places'].includes(n[0])).map(([id,i,l])=>`<button class="nav ${route===id?'active':''}" data-action="nav" data-page="${id}" aria-label="${l}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav><div class="top-actions"><button class="icon-btn" data-action="search" aria-label="Aile arşivinde ara">${icon('search')}</button><button class="icon-btn" data-action="nav" data-page="chat" aria-label="Mesajlar">${icon('messages-square')}</button><button class="icon-btn" data-action="menu" aria-label="Tüm bölümler">${icon('grid-2x2')}</button><button class="account-avatar" data-action="account" aria-label="Hesabım">${avatar(state.user)}</button></div></header>${demoMode?'<div class="demo-strip">ETKİLEŞİMLİ ÖNİZLEME · Kişiler ve tarihler örnektir. Değişiklikler yalnızca bu tarayıcıda saklanır.</div>':''}<main id="main" class="content page-enter" tabindex="-1">${({home,people,gallery,tree,calendar,history:historyPage,places,chat:communityChat,documents:communityDocuments,profile,admin,settings:settingsPage,archive:archivePage,connections:connectionsPage,groups:groupsPage}[route]||home)()}<footer class="footer"><span>Sarıçiçek · Aile Konağı</span>Aynı kökten, geleceğe birlikte.</footer></main></div><nav class="mobile-nav" aria-label="Mobil menü">${[['home','house','Konak'],['tree','git-fork','Soy ağacı'],['gallery','images','Avlu'],['calendar','calendar-days','Takvim'],['chat','messages-square','Mesajlar']].map(([id,i,l])=>`<button data-action="nav" data-page="${id}" class="${route===id?'active':''}">${icon(i)}${l}</button>`).join('')}</nav>`;hydrate();bindPage();window.familyEnhancements?.bind();window.archiveApp?.bind();}
function personForm(id){const p=state.people.find(p=>p.id===id)||{};modal(id?'Bir hayatın ayrıntıları':'Ailemize bir isim daha',form(input('Ad soyad','name',p.name,'text','required minlength="2" maxlength="120"')+input('Şehir / yer','place',p.place)+input('Ülke','country',p.country)+input('Doğum tarihi','birthDate',p.birthDate,'date')+input('Vefat tarihi (varsa)','deathDate',p.deathDate,'date')+input('Bilginin kaynağı','source',p.source,'text','placeholder="Aile büyüğünün anlatımı, kayıt…"')+area('Hayat hikâyesi','biography',p.biography),id?'Değişiklikleri kaydet':'Aileye ekle'));submitWith(async b=>{await api('/api/people'+(id?'/'+id:''),id?'PATCH':'POST',b);closeModal();await refresh();toast('Kişi bilgileri kaydedildi.');});if(id){$('.dialog-body').insertAdjacentHTML('beforeend',`<button class="text-btn" style="color:#a05e48;margin-top:20px" data-action="delete-person" data-id="${esc(id)}">${icon('archive')}Kaydı kaldır</button>`);hydrate();}}
function relationForm(){if(state.people.length<2){toast('Önce en az iki kişi ekleyin.');return;}const options=[['','Kişi seçin'],...state.people.map(p=>[p.id,p.name])];modal('Bir aile bağı kur',form(`<div class="field full"><div class="notice" style="margin:0">Ebeveyn ilişkisinde ilk kişi ebeveyn, ikinci kişi çocuktur. Eş ilişkisinde sıra önemli değildir.</div></div>`+select('Birinci kişi','personA',options,personId)+select('Bağ türü','type',[['parent','Ebeveyn → çocuk'],['spouse','Eş bağı'],['adoptive','Evlat edinen → çocuk']])+select('İkinci kişi','personB',options)+input('Evlilik tarihi (eş bağı için)','date','','date'),'Bağı kaydet'));submitWith(async b=>{if(!b.personA||!b.personB)throw Error('Her iki kişiyi seçin.');if(b.type!=='spouse')b.date=null;await api('/api/relations','POST',b);closeModal();await refresh();toast('Aile bağı kaydedildi.');});}
function photoForm(){modal('Bir anıyı geleceğe bırak',`<form id="modal-form"><label class="upload-zone" id="drop-zone"><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Fotoğraf seç" required><div id="photo-preview">${icon('images')}<h3>Her fotoğrafın bir hikâyesi var.</h3><p>Fotoğrafını buraya bırak veya cihazından seç.</p><span class="btn">${icon('plus')}Fotoğraf seç</span><br><small>JPEG, PNG, WebP · En fazla 8 MB</small></div></label><div class="form-grid">${input('Bu anıya bir başlık','title','','text','required maxlength="160" placeholder="Bir yaz akşamı, hep birlikte…"')}${input('Çekildiği tarih (biliniyorsa)','date','','date')}${select('Kim görebilir?','uploadVisibility',[['family','Bütün aile'],['private','Yalnızca ben'],['custom','Kişi veya grup seç (önce özel kaydedilir)']])}${input('Nerede çekildi?','place','','text','placeholder="Şehir, köy veya mekân"')}<div class="field"><label>Fotoğraftakiler</label><div class="tags-picker">${state.people.map(p=>`<label class="tag-check"><input type="checkbox" name="peopleIds" value="${esc(p.id)}">${esc(p.name)}</label>`).join('')||'<small>Önce soy ağacına kişi ekleyin.</small>'}</div></div>${area('Ardındaki hikâye','description','','placeholder="Bu anıyı unutulmaz yapan neydi?"')}</div>${!isStaff()?'<div class="notice">Paylaşımın, moderatör onayından sonra aile arşivinde görünür.</div>':''}<div class="form-error" role="alert"></div><progress class="progress" id="upload-progress" value="0" max="100" hidden></progress><div class="form-actions">${button('Vazgeç','close',null,'','type="button"')}<button class="btn primary" type="submit">${icon('arrow-up-right')}Anıyı paylaş</button></div></form>`);let photoData='';const zone=$('#drop-zone'),fileInput=$('#photo-file');async function choose(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('8 MB’tan küçük JPEG, PNG veya WebP seçin.');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Dosya okunamadı.'));reader.readAsDataURL(file);});photoData=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,2400/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.87));};im.onerror=()=>reject(Error('Görüntü dosyası okunamadı.'));im.src=raw;});$('#photo-preview').innerHTML=`<img src="${photoData}" alt="Yükleyeceğiniz fotoğrafın önizlemesi"><small>${esc(file.name)} · Değiştirmek için dokun</small>`;fileInput.required=false;}
 fileInput.addEventListener('change',()=>choose(fileInput.files[0]).catch(e=>{$('.form-error',dialog).textContent=e.message;photoData='';fileInput.value='';fileInput.required=true;}));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragover');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');choose(e.dataTransfer.files[0]).catch(e=>$('.form-error',dialog).textContent=e.message);});submitWith(async(b,f)=>{if(!photoData)throw Error('Önce bir fotoğraf seçin.');const progress=$('#upload-progress');progress.hidden=false;progress.value=30;const result=await api('/api/photos','POST',{...b,visibility:b.uploadVisibility==='family'?'family':'private',data:photoData,peopleIds:new FormData(f).getAll('peopleIds')});progress.value=100;closeModal();await refresh();toast(result.status==='pending'?'Fotoğrafın onaya gönderildi.':'Fotoğraf kaydedildi.');if(b.uploadVisibility==='custom')await exAudience('photo',result.id);});}
function photoDetail(id){const p=state.photos.find(p=>p.id===id);if(!p)return;const canEdit=isStaff()||p.createdBy===state.user.id;modal('Anının hikâyesi',`<img class="image-view" src="${esc(p.url)}" alt="${esc(p.title)}"><h3>${esc(p.title)}</h3><div class="meta-line"><span>${dateText(p.date)}</span><span>${esc(p.place)}</span></div><p class="image-desc">${esc(p.description)}</p><div class="row" style="flex-wrap:wrap">${(p.peopleIds||[]).map(id=>state.people.find(p=>p.id===id)).filter(Boolean).map(p=>`<button class="pill" data-action="profile" data-id="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div><div class="form-actions">${aButton('Bir hatıra ekle','photo-memory',p.id)}${aButton('Bu fotoğrafı aileye sor','photo-question',p.id)}${canEdit?aButton('Etiketler ve gizlilik','photo-settings',p.id)+aButton('Fotoğrafı iyileştir','photo-enhance',p.id):''}${button('İndir','download-photo','download','','data-id="'+esc(p.id)+'"')}${canEdit?button('Düzenle','edit-photo','pencil','','data-id="'+esc(p.id)+'"')+button('Kaldır','delete-content','archive','danger','data-id="'+esc(p.id)+'" data-table="photos"'):''}</div>`,true);}
function contentEdit(table,id){const p=state[table].find(x=>x.id===id);if(!p)return;modal(table==='photos'?'Anıyı düzenle':'Olayı düzenle',form(input('Başlık','title',p.title,'text','required maxlength="160"')+input('Tarih','date',p.date,'date',table==='events'?'required':'')+input('Yer','place',p.place)+area('Açıklama','description',p.description)));submitWith(async b=>{await api('/api/'+table+'/'+id,'PATCH',b);closeModal();await refresh();toast('Değişiklikler kaydedildi.');});}
function eventForm(story=false){modal(story?'Hikâyemize bir sayfa ekle':'Birlikte hatırlayacağımız bir gün',form(input('Başlık','title','','text','required maxlength="160"')+select('Kayıt türü','type',Object.entries(types),story?'story':'gathering')+input('Tarih','date','','date','required')+input('Yer / tören bilgisi','place')+select('İlgili kişi (isteğe bağlı)','personId',[['','Kişi seçilmedi'],...state.people.map(p=>[p.id,p.name])])+area('Ayrıntılar','description'),'Aileyle paylaş'));submitWith(async b=>{await api('/api/events','POST',b);closeModal();await refresh();toast(isStaff()?'Aile takvimine eklendi.':'Kaydın moderatör onayına gönderildi.');});}
function eventDetail(id){const e=state.events.find(x=>x.id===id)||upcoming().find(x=>x.id===id);if(!e)return;const actual=state.events.some(x=>x.id===id),canEdit=actual&&(isStaff()||e.createdBy===state.user.id);modal(esc(types[e.type]||'Aile takvimi'),`<span class="eyebrow">${dateText(e.date)}</span><h3>${esc(e.title)}</h3><p class="image-desc">${esc(e.description||'Bu tarih aile kayıtlarından otomatik hesaplanır.')}</p><div class="meta-line">${icon('map-pin')}${esc(e.place||'Yer belirtilmedi')}</div><div class="form-actions">${e.personId?button('Kişiyi gör','profile','user','','data-id="'+esc(e.personId)+'"'):''}${actual?aButton('Etkinlik albümü','event-album',e.id):''}${e.type==='gathering'&&e.status==='approved'?button('Katılım durumu','attendance','users-round','','data-id="'+esc(e.id)+'"'):''}${canEdit?button('Düzenle','edit-event','pencil','','data-id="'+esc(id)+'"')+button('Kaldır','delete-content','archive','danger','data-id="'+esc(id)+'" data-table="events"'):''}</div>`);}
function inviteForm(){modal('Ailemize bir davet',form(input('Üyenin e-posta adresi','email','','email','required placeholder="isim@alanadiniz.com"')+select('Yetkisi','role',[['member','Aile üyesi'],['moderator','Moderatör']])+`<div class="field full"><div class="notice">Davet bağlantısı 7 gün geçerlidir. Üye, davet edildiği e-posta hesabıyla giriş yapar. Daveti oluşturmak e-posta göndermez; bağlantıyı kendiniz paylaşabilirsiniz.</div></div>`,'Davet bağlantısı oluştur'));submitWith(async b=>{const result=await api('/api/invites','POST',b);showLink(result,'Davet hazır');adminData=null;await refresh();});}
function showLink(result,title){modal(title,result.demo?`<div class="notice">Önizlemede davet örneği kaydedildi. Gerçek sunucuda aynı işlem, tek kullanımlık ve süreli bir kayıt bağlantısı üretir. E-posta gönderilmedi.</div>`:`<p style="font-size:12px;margin-bottom:18px">Bu bağlantıyı yalnızca ilgili kişiyle paylaşın.</p>${input('Kayıt bağlantısı','share-link',result.url,'text','readonly')}<div class="form-actions">${button('Bağlantıyı kopyala','copy-link','copy','primary')}</div>`);}
function confirmAction(title,desc,callback){modal(title,`<p style="font-size:13px">${desc}</p><div class="form-error" role="alert"></div><div class="form-actions">${button('Vazgeç','close')}${button('Onayla','confirm-action','check','primary')}</div>`);$('[data-action="confirm-action"]').addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await callback();closeModal();await refresh();}catch(err){$('.form-error',dialog).textContent=err.message;e.currentTarget.disabled=false;}},{once:true});}
function searchDialog(treeOnly=false){modal(treeOnly?'Ağaçta birini bul':'Ailemizde ara',`<label class="search" style="width:100%;margin-bottom:15px">${icon('search')}<input id="global-search" autofocus placeholder="Bir isim, bir yer, bir anı…" aria-label="Aile arşivinde ara"></label><div id="search-results"><p style="font-size:12px">Aramak için birkaç harf yazın.</p></div>`);$('#global-search').focus();$('#global-search').addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase('tr'),match=s=>s.toLocaleLowerCase('tr').includes(q);let results=[];if(q){results.push(...state.people.filter(p=>match(p.name+' '+p.place+' '+p.country)).map(p=>({id:p.id,title:p.name,desc:p.place,action:treeOnly?'focus-person':'profile',i:'user'})));if(!treeOnly){results.push(...state.photos.filter(p=>match(p.title+' '+p.place)).map(p=>({id:p.id,title:p.title,desc:'Avlu',action:'photo',i:'image'})),...state.events.filter(p=>match(p.title+' '+p.description)).map(p=>({id:p.id,title:p.title,desc:types[p.type],action:'event-detail',i:'calendar-days'})));}}$('#search-results').innerHTML=results.slice(0,30).map(r=>`<button class="search-result" data-action="${r.action}" data-id="${esc(r.id)}">${icon(r.i)}<span><h3>${esc(r.title)}</h3><small>${esc(r.desc)}</small></span></button>`).join('')||(q?'<p style="font-size:12px">Bu aramayla eşleşen bir kayıt yok.</p>':'');hydrate();});}
function bindPage(){for(const id of ['people-search','gallery-search'])$('#'+id)?.addEventListener('input',e=>{const start=e.target.selectionStart;query=e.target.value;page=1;render();const el=$('#'+id);el.focus();el.setSelectionRange(start,start);});$('#tree-search')?.addEventListener('focus',()=>searchDialog(true));
 $('#settings-form')?.addEventListener('submit',e=>saveSettings(e));$('#domain-form')?.addEventListener('submit',e=>saveSettings(e));
 $$('[data-user-role]').forEach(el=>el.addEventListener('change',()=>{const u=adminData.users.find(u=>u.id===el.dataset.userRole),newRole=el.value;el.value=u.role;confirmAction('Üye yetkisini değiştir',`${esc(u.name)} için yeni yetki: ${roleName[newRole]}. Mevcut oturumları kapatılır.`,async()=>{await api('/api/users/'+u.id,'PATCH',{role:newRole,active:u.active});adminData=null;toast('Yetki güncellendi.');});}));
 const viewport=$('.tree-viewport');if(viewport){let drag=null;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.pointerType==='touch')return;drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);});viewport.addEventListener('pointermove',e=>{if(drag){viewport.scrollLeft=drag.left+drag.x-e.clientX;viewport.scrollTop=drag.top+drag.y-e.clientY;}});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointercancel',()=>drag=null);}}
async function saveSettings(e){e.preventDefault();const form=e.currentTarget,btn=$('[type=submit]',form);btn.disabled=true;try{await api('/api/settings','PATCH',Object.fromEntries(new FormData(form)));await refresh();toast('Aile ayarları kaydedildi.');}catch(err){$('.form-error',form).textContent=err.message;}finally{btn.disabled=false;}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function calendarExport(){const escapeIcs=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const entries=upcoming().map(e=>`BEGIN:VEVENT\r\nUID:${e.id}@saricicek-family\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z')}\r\nDTSTART;VALUE=DATE:${e.date.replace(/-/g,'')}\r\nSUMMARY:${escapeIcs(e.title)}\r\nDESCRIPTION:${escapeIcs(types[e.type])}\r\nEND:VEVENT`);download('saricicek-aile-takvimi.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Saricicek Family//TR\r\n'+entries.join('\r\n')+'\r\nEND:VCALENDAR','text/calendar;charset=utf-8');}
async function handle(action,el){const id=el.dataset.id;await window.familyEnhancements?.handle(action,el);await window.archiveApp?.handle(action,el);switch(action){
 case'close':closeModal();break;
 case'nav':if(dialog.open)closeModal();adminData=null;go(el.dataset.page);break;
 case'menu':modal('Ailemizin dünyası',`<nav class="all-sections" aria-label="Tüm bölümler">${navItems.map(([id,i,l])=>button(l,'nav',i,'','data-page="'+id+'"')).join('')}${isStaff()?button('Yönetim paneli','nav','shield-check','','data-page="admin"'):''}${isOwner()?button('Aile ayarları','nav','settings-2','','data-page="settings"'):''}</nav>`);break;
 case'account':modal('Aile hesabın',`<div class="row">${avatar(state.user,'large')}<div><h3>${esc(state.user.name)}</h3><p style="font-size:12px">${esc(state.user.email)}</p><span class="pill">${roleName[state.user.role]}</span></div></div><div class="form-actions">${aButton('İki aşamalı doğrulama','security')}${aButton('Kolay görünüm','simple')}${button('Oturumu kapat','logout','log-out')}${!isOwner()?button('Hesabımı sil','delete-account','trash-2','danger'):''}</div>${demoMode?`<div class="notice">Önizlemede yetkileri dene:</div><div class="row" style="flex-wrap:wrap">${['owner','moderator','member'].map(r=>button(roleName[r],'demo-role',null,'small','data-role="'+r+'"')).join('')}</div>`:''}`);break;
 case'logout':sessionStorage.removeItem('sf-factor');await familyStopLocation(false).catch(()=>{});window.familyEnhancements?.cleanup();if(hostedAuth){location.assign('/signout-with-chatgpt?return_to=%2F');break;}await api('/api/logout','POST',{});closeModal();state=null;loginScreen();break;
 case'profile':if(dialog.open)closeModal();go('profile',id);break;
 case'add-person':personForm();break;
 case'edit-person':personForm(id);break;
 case'delete-person':confirmAction('Kişiyi kayıtlardan kaldır', 'Bu kayıt yönetim panelindeki kaldırılan kayıtlardan geri yüklenebilir.',async()=>{await api('/api/people/'+id,'DELETE',{});route='people';toast('Kayıt kaldırıldı.');});break;
 case'add-relation':relationForm();break;
 case'upload':photoForm();break;
 case'load-photos':{const more=await api('/api/photos?offset='+state.photos.length);const ids=new Set(state.photos.map(p=>p.id));state.photos.push(...more.items.filter(p=>!ids.has(p.id)));state.photosComplete=!more.hasMore;render();break;}
 case'photo':photoDetail(id);break;
 case'edit-photo':contentEdit('photos',id);break;
 case'edit-event':contentEdit('events',id);break;
 case'download-photo':{const p=state.photos.find(p=>p.id===id);const response=await fetch(p.url);if(!response.ok)throw Error('Fotoğraf indirilemedi.');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.title.replace(/[^\p{L}\p{N} -]/gu,'')+(blob.type==='image/png'?'.png':blob.type==='image/webp'?'.webp':'.jpg');a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);break;}
 case'delete-content':confirmAction('Kaydı kaldır', 'Kayıt aile arşivinden kaldırılır; yönetim panelinden geri yüklenebilir.',async()=>{await api('/api/'+el.dataset.table+'/'+id,'DELETE',{});toast('Kayıt kaldırıldı.');});break;
 case'filter':filter=el.dataset.filter;page=1;render();break;
 case'prev-page':page=Math.max(1,page-1);render();break;
 case'next-page':page++;render();break;
 case'focus-person':if(dialog.open)closeModal();treeFocus=id;zoom=1;go('tree');break;
 case'tree-reset':treeFocus='';render();break;
 case'zoom-in':case'zoom-out':zoom=Math.max(.35,Math.min(2,zoom+(action==='zoom-in'?.15:-.15)));$('.tree-canvas').style.transform=`scale(${zoom})`;$('#zoom-label').textContent=Math.round(zoom*100)+'%';break;
 case'zoom-fit':{const board=$('.tree-viewport'),canvas=$('.tree-canvas');zoom=Math.min(1,board.clientWidth/parseFloat(canvas.style.width),board.clientHeight/parseFloat(canvas.style.height));canvas.style.transform=`scale(${zoom})`;$('#zoom-label').textContent=Math.round(zoom*100)+'%';board.scrollTo(0,0);break;}
 case'add-event':eventForm();break;
 case'add-story':eventForm(true);break;
 case'event-detail':eventDetail(id);break;
 case'month-prev':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);selectedDate=null;render();break;
 case'month-next':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);selectedDate=null;render();break;
 case'select-day':selectedDate=el.dataset.date;render();break;
 case'clear-day':selectedDate=null;render();break;
 case'export-calendar':calendarExport();toast('Takvim dosyası indirildi.');break;
 case'search':searchDialog();break;
 case'notifications':{const day=new Date().toLocaleDateString('en-CA');modal('Ailemizde yaklaşan günler',eventRows(upcoming().filter(e=>e.date>=day).slice(0,8))+button('Cihazımda hatırlat','native-reminders','bell'));break;}
 case'invite':inviteForm();break;
 case'copy-link':try{await navigator.clipboard.writeText($('#f-share-link').value);toast('Bağlantı kopyalandı.');}catch{$('#f-share-link').select();toast('Bağlantı seçildi. Kopyalamak için Ctrl+C kullanın.');}break;
 case'cancel-invite':confirmAction('Daveti iptal et', 'Bu davet bağlantısı artık kullanılamayacak.',async()=>{await api('/api/invites/'+id,'DELETE',{});adminData=null;});break;
 case'approve':case'reject':await api('/api/'+el.dataset.table+'/'+id,'PATCH',{status:action==='approve'?'approved':'rejected'});await refresh();toast(action==='approve'?'Katkı aile arşivinde yayımlandı.':'Katkı yayımlanmadı.');break;
 case'toggle-user':{const u=adminData.users.find(u=>u.id===id);confirmAction(u.active?'Üyeliği dondur':'Üyeliği etkinleştir',`${esc(u.name)} hesabının durumu değiştirilecek.`,async()=>{await api('/api/users/'+id,'PATCH',{role:u.role,active:u.active?0:1});adminData=null;});break;}
 case'reset-link':showLink(await api('/api/reset-link','POST',{userId:id}),'Şifre yenileme bağlantısı');break;
 case'restore':await api('/api/restore','POST',{id,table:el.dataset.table});adminData=null;await refresh();toast('Kayıt geri yüklendi.');break;
 case'export':download('saricicek-aile-arsivi.json',JSON.stringify(await api('/api/export'),null,2));toast('Arşiv kayıtları indirildi.');break;
 case'mail-plan':{if(!state.settings.mailDomain){toast('Önce alan adını kaydedin.');break;}if(!adminData)adminData=await api('/api/admin');const csv=s=>'"'+String(s).replace(/"/g,'""')+'"';const safe=s=>/^[=+\-@\t\r]/.test(s)?"'"+s:s;const users=adminData.users;download('aile-eposta-plani.csv','\uFEFFAd Soyad,Önerilen adres,Durum\n'+users.map((u,i)=>[csv(safe(u.name)),csv('uye'+(i+1)+'@'+state.settings.mailDomain),csv('Sağlayıcıda oluşturulmalı')].join(',')).join('\n'),'text/csv;charset=utf-8');break;}
 case'demo-role':await api('/api/demo-role','POST',{role:el.dataset.role});if(dialog.open)closeModal();adminData=null;route='home';await refresh();toast('Önizleme rolü: '+roleName[state.user.role]);break;
 }}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;handle(el.dataset.action,el).catch(err=>toast(err.message));});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state){e.preventDefault();searchDialog();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(state){readRoute();render();}});
function loginScreen(error=''){if(hostedAuth){hostedLoginScreen(error);return;}const fragment=location.hash.slice(1),invite=fragment.startsWith('invite='),reset=fragment.startsWith('reset='),special=invite||reset;$('#app').innerHTML=`<div class="login-page"><section class="login-visual"><div class="brand"><img src="assets/mark.svg" alt=""><span><strong>Sarıçiçek</strong><small>AİLE KONAĞI</small></span></div><div><span class="eyebrow" style="color:#e0d2a5">AYNI KÖKTEN, GELECEĞE BİRLİKTE</span><h1 style="margin-top:20px">Köklerimiz bir.<br><em>Hikâyemiz sonsuz.</em></h1><p>Ailemizin dünyanın her yerinden buluştuğu, hatıralarını birlikte yaşattığı özel konağı.</p></div></section><section class="login-panel"><span class="eyebrow">YALNIZCA AİLEMİZE AİT</span><h2>${invite?'Ailemize hoş geldin.':reset?'Yeni bir başlangıç.':'Evine hoş geldin.'}</h2><p>${invite?'Adını ve şifreni belirleyerek aile konağına katıl.':reset?'Hesabın için yeni bir şifre belirle.':'Anılarımıza, hikâyelerimize ve birbirimize açılan kapı.'}</p><form id="login-form" class="stack">${invite?input('Ad soyad','name','','text','required minlength="2" autocomplete="name"'):''}${!special?input('E-posta adresi','email','','email','required autocomplete="username"'):''}${input(special?'Yeni şifre':'Şifre','password','','password',`required ${special?'minlength="12"':''} maxlength="256" autocomplete="${special?'new-password':'current-password'}"`)}${special?'<small class="muted">En az 12 karakter kullanın.</small>':''}<div class="form-error" role="alert">${esc(error)}</div><button class="btn primary" type="submit">${invite?'Aileye katıl':reset?'Şifremi yenile':'Konağa giriş yap'}${icon('arrow-right')}</button></form>${!special?'<div class="notice">Katılmak veya şifrenizi yenilemek için aile yöneticisinden davet / yenileme bağlantısı isteyin.</div>':''}${demoMode?button('Etkileşimli önizlemeyi aç','open-demo','arrow-up-right'):''}<footer>${icon('lock-keyhole')} Kişisel arşivimiz yalnızca yetkili aile üyelerine açıktır.</footer></section></div>`;hydrate();$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f)),btn=$('[type=submit]',f);btn.disabled=true;try{if(demoMode&&!special){state=await api('/api/bootstrap');render();return;}const result=await api(invite?'/api/accept-invite':reset?'/api/reset-password':'/api/login','POST',{...b,...(special?{token:fragment.split('=')[1]}:{})});window.history.replaceState(null,'',location.pathname+location.search);if(reset){loginScreen('Şifreniz yenilendi. Şimdi giriş yapabilirsiniz.');return;}csrf=result.csrf;route='home';await refresh();}catch(err){$('.form-error',f).textContent=err.message;}finally{btn.disabled=false;}});$('[data-action="open-demo"]')?.addEventListener('click',async()=>{route='home';await refresh();});}
function hostedLoginScreen(error=''){
 const invite=location.hash.startsWith('#invite=');
 $('#app').innerHTML=`<div class="login-page"><section class="login-visual"><div class="brand"><img src="assets/mark.svg" alt=""><span><strong>Sarıçiçek</strong><small>AİLE KONAĞI</small></span></div><div><span class="eyebrow">AYNI KÖKTEN, GELECEĞE BİRLİKTE</span><h1>Köklerimiz bir.<br><em>Hikâyemiz sonsuz.</em></h1><p>Dünyanın neresinde olursak olalım, ailemizin buluştuğu özel konak.</p></div></section><section class="login-panel"><span class="eyebrow">YALNIZCA AİLEMİZE AİT</span><h2>${invite?'Ailemize hoş geldin.':'Evine hoş geldin.'}</h2><p>${invite?'Davetin gönderildiği e-posta hesabıyla giriş yaparak aileye katıl.':'Aile arşivine erişim için yetkili hesabınla giriş yap.'}</p><div class="form-error" role="alert">${esc(error)}</div>${invite&&csrf?`<form id="hosted-invite" class="stack">${input('Ad soyad','name','','text','required minlength="2" autocomplete="name"')}<button class="btn primary" type="submit">Aileye katıl ${icon('arrow-right')}</button></form>`:`<a class="btn primary" target="_top" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/'+location.hash)}">ChatGPT ile giriş yap ${icon('arrow-right')}</a>`}<div class="notice">Aile üyeliği davetle açılır. Giriş yapmak tek başına aile kayıtlarına erişim sağlamaz.</div><footer>${icon('lock-keyhole')} Ailemizin özel arşivi</footer></section></div>`;
 hydrate();$('#hosted-invite')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,btn=$('button',f);btn.disabled=true;try{const result=await api('/api/accept-invite','POST',{name:new FormData(f).get('name'),token:location.hash.slice(8)});csrf=result.csrf;window.history.replaceState(null,'',location.pathname);route='home';await refresh();}catch(err){$('.form-error').textContent=err.message;}finally{btn.disabled=false;}});
}
async function boot(){
 if(demo){readRoute();await refresh();return;}
 try{const config=await api('/api/config');hostedAuth=config.auth==='chatgpt';if(config.demo){demoMode=true;demo=window.makeDemo();readRoute();await refresh();return;}
 if(!hostedAuth&&(location.hash.startsWith('#invite=')||location.hash.startsWith('#reset='))){loginScreen();return;}
 if(!config.configured){loginScreen('İlk yönetici hesabı sunucuda oluşturulmalı.');return;}
 const session=await api('/api/me');csrf=session.csrf;
 if(hostedAuth&&!session.user){loginScreen(location.hash.startsWith('#invite=')?'':'Bu hesap aileye henüz davet edilmedi veya erişimi donduruldu.');return;}
 if(hostedAuth&&location.hash.startsWith('#invite='))window.history.replaceState(null,'',location.pathname);
 readRoute();await refresh();}catch(e){loginScreen(e.message==='Oturum açmanız gerekiyor.'?'':e.message);}
}
boot();

// Optional browser tools share the currently authorized interface state.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 try{Promise.resolve(document.modelContext.registerTool({name:'search_family_members',title:'Aile üyelerini ara',description:'Search the family members visible to the signed-in user; returns matching profile IDs and names.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!state)throw Error('Önce oturum açın.');if(!input||typeof input.query!=='string'||input.query.length>120)throw Error('Geçerli bir arama girin.');return state.people.filter(p=>p.name.toLocaleLowerCase('tr').includes(input.query.toLocaleLowerCase('tr'))).slice(0,24).map(p=>({id:p.id,name:p.name}));}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
}
